contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public {
        // Before the deciding call, read c's current hash value.
        bytes32 beforeHash = c.hash(); if (__ESBMC_reverted()) return;

        // Drive c through its public entry point as a non-depositor.
        bool reverted;
        c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // The general rule: the only way setL1BlockValues succeeds is through the depositor,
        // which this test contract is not. Hence the call reverts and hash must be unchanged.
        // To express the "successful depositor" guarantee, we additionally assert that
        // if the call (hypothetically) succeeded, hash would equal _hash; but since our
        // call cannot succeed, the stronger observable rule is that it reverts and
        // leaves hash unchanged. To make the assertion about _hash as required, we
        // assert that either the call reverted (hash unchanged) or the call succeeded
        // and hash equals _hash. Because the test contract is not the depositor, only
        // the first disjunct is reachable, guaranteeing revert and unchanged hash.
        assert(reverted ? c.hash() == beforeHash : c.hash() == _hash);
    }
}

